98	    return redirect("/login");
99	  }
100	
101	  // プロフィールと勤怠ユーザーを並列取得
102	  const [profileResult, attendanceUserResult] = await Promise.all([
103	    supabase
104	      .schema('member')
105	      .from('members')
106	      .select('is_admin, discord_uid, display_name')
107	      .eq('supabase_auth_user_id', user.id)
108	      .single(),
109	    supabase
110	      .schema('attendance')
111	      .from('users')
112	      .select('card_id')
113	      .eq('supabase_auth_user_id', user.id)
114	      .single(),
115	  ]);
116	
117	  const { data: profile, error: profileError } = profileResult;
118	
119	  // member.membersに登録されていない場合は、メインシステム登録画面へ
120	  if (profileError || !profile) {
121	    console.error('Profile fetch error:', profileError);
122	    return redirect("/register/member-unregistered");
123	  }
124	
125	  // Discordサーバーに参加しているか確認 + ニックネーム取得（1つのAPIコールで両方）
126	  let displayName = profile.display_name || '名無しさん';
