137	        const parts = discordCheck.nickname.split('|');
138	        const nameOnly = parts.length > 1 ? parts[parts.length - 1].trim() : discordCheck.nickname.trim();
139	        displayName = nameOnly;
140	        // DBにもキャッシュ保存（非同期）
141	        const adminClient = await createSupabaseAdminClient();
142	        adminClient.schema('member').from('members')
143	          .update({ display_name: nameOnly })
144	          .eq('discord_uid', profile.discord_uid!)
145	          .then(() => console.log(`Cached display_name for ${profile.discord_uid}`));
146	      }
147	    } catch (error) {
148	      if (error instanceof Error && error.message === 'NEXT_REDIRECT') {
149	        throw error;
150	      }
151	      console.error('Discord membership check failed:', error);
152	      return redirect("/register/discord-required");
